      { kind: "grid", items: [{ title: "Grade I", text: "Internal piles that do not prolapse outside the anus." }, { title: "Grade II", text: "Prolapse during straining but reduce spontaneously." }, { title: "Grade III", text: "Prolapse and usually need manual reduction." }, { title: "Grade IV", text: "Remain prolapsed and cannot be reduced." }, { title: "External Piles", text: "Swollen tissue around the anal opening, sometimes thrombosed." }, { title: "Mixed Piles", text: "Features of both internal and external haemorrhoids." }] }
